window.kopMailSelectThread=function(e){document.querySelectorAll(`#mail-message-list .kop-mail-thread-active`).forEach(e=>{e.classList.remove(`kop-mail-thread-active`),e.querySelector(`[data-thread-chevron]`)?.classList.add(`kop-mail-chevron-hidden`)});let t=e.closest(`li`);t.classList.add(`kop-mail-thread-active`),t.querySelector(`[data-thread-chevron]`)?.classList.remove(`kop-mail-chevron-hidden`)};